def paras(w, *texts):
    for text in texts:
        w.p(text)


def sub(w, heading, *texts):
    w.h(heading)
    paras(w, *texts)


def _r(refs, key, fallback):
    value=(refs or {}).get(key, fallback)
    if isinstance(value, dict):
        value=value.get('ref', value.get('caption', fallback))
    return 'См. '+str(value) if key in (refs or {}) else str(value)


def write_introduction(w):
    w.structural('ВВЕДЕНИЕ')
    paras(w,
     'Обслуживание физических лиц в отделениях банка объединяет ведение клиентов, счетов, банковских карт, переводов и кредитных договоров. Результат каждого обращения должен быть согласован с учётом: документ подтверждает сохранённый факт, остатки отражают проведённые операции, график соответствует условиям договора.',
     'При раздельном ведении сведений сотрудники повторно вводят реквизиты и вручную сверяют связанные записи. Руководителю операционного направления необходимо обеспечить правильное и своевременное обслуживание при ограниченном составе сотрудников. Удаление проверок увеличивает риск ошибок, а их расширение расходует ресурс обслуживания.',
     'Цель работы — разработать проект банковской информационной системы, которая поддерживает согласованное оформление операций и позволяет проверить сокращение полного ручного труда. Объект проектирования — обслуживание физических лиц в отделениях; предмет — данные, функции, процессы и программные средства учёта и контроля.',
     'Постановка назначения и качества предшествует выбору функций и технологий. Далее представлены модели данных и процессов, архитектура, технические решения и программа испытаний. Документ определяет проект и способы получения свидетельств; фактические результаты проверки реализации предстоит получить на испытательном стенде.')


